import React from 'react';

import { getInputDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { updateHikingObstacle } from '../../@services/hikingObstacles.service';
import { IHikingObstacleUpdateDTO } from '../../@types/DTO/hikingObstacles.dto.types';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingObstacleOne } from '../../@types/hikingObstacles.types';

interface IHikingObstacleBaseParamsFormProps {
  oneHikingObstacleData: IHikingObstacleOne;
  hikingData: IHikingData;
}

const HikingObstacleBaseParamsForm: React.FC<IHikingObstacleBaseParamsFormProps> = ({
  oneHikingObstacleData,
  hikingData,
}) => {
  const [isLoading, setIsLoading] = React.useState(false);

  type T = Omit<IHikingObstacleUpdateDTO, 'id' | 'id_hiking'>;

  const handleInputChange =
    <K extends keyof T>(field: keyof T) =>
    async (value: T[K]) => {
      try {
        setIsLoading(true);
        const upData: IHikingObstacleUpdateDTO = {
          id: oneHikingObstacleData.id,
          id_hiking: hikingData.id,
          [field]: value,
        };
        await updateHikingObstacle(upData);
        notificationHelper.success('Сохранено');
      } finally {
        setIsLoading(false);
      }
    };

  return (
    <>
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            type={InputTypes.datetimeLocal}
            label="Дата входа"
            defaultValue={getInputDate(oneHikingObstacleData.date_in)}
            onRealChange={handleInputChange('date_in')}
            disabled={isLoading}
          />
        </PohCol>
        <PohCol sm={6}>
          <PohInput
            type={InputTypes.datetimeLocal}
            label="Дата выхода"
            defaultValue={getInputDate(oneHikingObstacleData.date_out)}
            onRealChange={handleInputChange('date_out')}
            disabled={isLoading}
          />
        </PohCol>
      </PohRow>

      <PohInput
        type={InputTypes.textarea}
        label="Описание"
        placeholder="Краткое описание"
        defaultValue={oneHikingObstacleData.description}
        name="hiking-obstacle-description"
        id="hiking-obstacle-description"
        onRealChange={handleInputChange<'description'>('description')}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />
      <PohInput
        type={InputTypes.textarea}
        label="Описание входа"
        placeholder="Например: Подъем на перевал осуществлялся со стороны реки Белая, сначала по натоптанной троке, затем по леднику"
        defaultValue={oneHikingObstacleData.description_in}
        name="hiking-obstacle-description_in"
        id="hiking-obstacle-description_in"
        onRealChange={handleInputChange<'description_in'>('description_in')}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />

      <PohInput
        type={InputTypes.textarea}
        label="Описание выхода"
        placeholder="например: Спускались с перевала в долину реки Аккем по хорошо натоптанной тропе"
        defaultValue={oneHikingObstacleData.description_out}
        name="hiking-obstacle-description_out"
        id="hiking-obstacle-description_out"
        onRealChange={handleInputChange<'description_out'>('description_out')}
        disabled={isLoading}
        wrapperClassName="mb-2"
      />
    </>
  );
};

export default HikingObstacleBaseParamsForm;
