import React from 'react';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCheckbox from '@ui-kit/Checkbox';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import { obstacleTypeNameResource } from '../../Obstacles/@resources/obstacles.resource';
import { getHikingDataAsync } from '../@services/hiking.service';
import {
  addMemberToHikingObstacle,
  deleteMemberFromHikingObstacle,
  getHikingOneObstacle,
} from '../@services/hikingObstacles.service';
import { IHikingData } from '../@types/hiking.types';
import { IHikingObstacleOne } from '../@types/hikingObstacles.types';
import HikingObstacleBaseParamsForm from './components/HikingObstacleBaseParamsForm';
import HikingObstaclePhotos from './components/HikingObstaclePhotos';

interface IHikingObstacleEditPage {
  id_hiking: number;
  id_hiking_obstacle: number;
}

const HikingObstacleEditPage: React.FC<IHikingObstacleEditPage> = ({
  id_hiking,
  id_hiking_obstacle,
}) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [hikingObstacleData, setHikingObstacleData] = React.useState<IHikingObstacleOne | null>(
    null,
  );
  const [isLoading, setIsLoading] = React.useState(true);
  const [savingUserId, setSavingUserId] = React.useState<number | null>(null);

  React.useEffect(() => {
    const start = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
      await getHikingOneObstacle(id_hiking_obstacle).then(setHikingObstacleData);
    };

    start().finally(() => setIsLoading(false));
  }, [id_hiking, id_hiking_obstacle]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) {
    return null;
  }

  if (!hikingObstacleData) {
    return null;
  }

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
          { href: `/hiking/${id_hiking}/obstacles`, text: 'Локальные препятствия и POI' },
          {
            href: `/hiking/${id_hiking}/obstacles/${id_hiking_obstacle}`,
            text: hikingObstacleData.obstacle.name,
            active: true,
          },
        ]}
      />
      <PageHeader
        title={
          <span>
            {obstacleTypeNameResource[hikingObstacleData.obstacle.type]}&nbsp;«
            {hikingObstacleData.obstacle.name}»
            <br />
            <small className="text-muted">в походе «{hikingData.name}»</small>
          </span>
        }
      >
        &nbsp;
        {/* <PohButton
          onClick={() => push(`/obstacles/${getUrlFromObstacleType(obstacleData.type)}/${obstacleData.id}`)}
          variant={ButtonVariant.Light}
        >
          Подробнее
        </PohButton> */}
      </PageHeader>

      <section>
        <PohRow>
          <PohCol sm={6}>
            <h5>Основные параметры</h5>
            <HikingObstacleBaseParamsForm
              oneHikingObstacleData={hikingObstacleData}
              hikingData={hikingData}
            />
          </PohCol>
          <PohCol sm={6}>
            <h5 className="mb-1">Участники</h5>
            <small className="mt-n1">Кто из участников был</small>
            <PohList
              data={hikingData.hikers.map((hiker) => {
                const memberData = hikingObstacleData.members.find(
                  (m) => m.user.id === hiker.idUser,
                );
                return {
                  key: hiker.idUser,
                  className: 'py-2',
                  children: (
                    <div className="d-flex justify-content-between align-items-center">
                      <div className="d-flex align-items-center">
                        <PohAva src={hiker.photo[50]} alt={hiker.name} className="me-2" />
                        <small style={{ lineHeight: 1 }}>
                          {hiker.name}
                          <br />
                          {hiker.surname}
                        </small>
                      </div>
                      {savingUserId === hiker.idUser ? (
                        <PohLoader />
                      ) : (
                        <PohCheckbox checked={!!memberData} />
                      )}
                    </div>
                  ),
                  onClick: async () => {
                    try {
                      setSavingUserId(hiker.idUser);
                      if (memberData) {
                        await deleteMemberFromHikingObstacle({
                          id_hiking: hikingData.id,
                          id: memberData.id,
                        });

                        setHikingObstacleData((cur) => {
                          return {
                            ...(cur as IHikingObstacleOne),
                            members: cur?.members.filter((m) => m.user.id !== hiker.idUser) ?? [],
                          };
                        });
                      } else {
                        const recordId = await addMemberToHikingObstacle({
                          id_hiking: hikingData.id,
                          id_hiking_obstacle: hikingObstacleData.id,
                          id_user: hiker.idUser,
                        });

                        setHikingObstacleData((cur) => {
                          return {
                            ...(cur as IHikingObstacleOne),
                            members: [
                              ...(cur?.members ?? []),
                              {
                                id: recordId,
                                user: {
                                  id: hiker.idUser,
                                  name: hiker.name,
                                  surname: hiker.surname,
                                  photo: hiker.photo[50],
                                },
                              },
                            ],
                          };
                        });
                      }
                    } finally {
                      setSavingUserId(null);
                    }
                  },
                  disabled: savingUserId !== null,
                };
              })}
            />
          </PohCol>
        </PohRow>
        <PohRow>
          <PohCol sm={12}>
            <HikingObstaclePhotos
              hikingData={hikingData}
              oneHikingObstacleData={hikingObstacleData}
              onChangePhotos={(up) => {
                setHikingObstacleData((cur) => {
                  return {
                    ...(cur as IHikingObstacleOne),
                    photos: up,
                  };
                });
              }}
            />
          </PohCol>
        </PohRow>
      </section>
    </PohContainer>
  );
};

export default HikingObstacleEditPage;
