import React, { FormEvent } from 'react';

import { getInputDate } from '@helpers/dateHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { updatePhotoOfHikingObstacle } from '../../@services/hikingObstacles.service';
import { IHikingObstacleOnePhotoUpdateDTO } from '../../@types/DTO/hikingObstacles.dto.types';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingObstacleOne, IHikingObstaclePhoto } from '../../@types/hikingObstacles.types';

interface IHikingObstaclePhotoEditFormProps {
  photo: IHikingObstaclePhoto;
  hikingData: IHikingData;
  hikingObstacle: IHikingObstacleOne;
  callback: (newPhoto: IHikingObstaclePhoto) => void;
}

const HikingObstaclePhotoEditForm: React.FC<IHikingObstaclePhotoEditFormProps> = ({
  photo,
  hikingData,
  hikingObstacle,
  callback,
}) => {
  const [data, setData] = React.useState<IHikingObstacleOnePhotoUpdateDTO>({
    id_hiking: hikingData.id,
    id_photo: photo.id,
    date: getInputDate(photo.date),
    comment: photo.comment,
  });

  const [isSaving, setIsSaving] = React.useState(false);

  type T = Pick<IHikingObstacleOnePhotoUpdateDTO, 'comment' | 'date'>;

  const handleInputChange = (field: keyof T) => (value: string) => {
    setData((fd) => ({
      ...fd,
      [field]: value,
    }));
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    try {
      setIsSaving(true);
      await updatePhotoOfHikingObstacle(data);
      callback({
        ...photo,
        date: new Date(data.date),
        comment: data.comment,
      });
      notificationHelper.success('Сохранено');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <PohRow className="mb-2">
        <PohCol sm={2}>Фото</PohCol>
        <PohCol sm={10}>
          <img src={photo.url} width={'100%'} />
        </PohCol>
      </PohRow>
      <PohInput
        required
        disabled={isSaving}
        type={InputTypes.datetimeLocal}
        label="Дата"
        value={data.date}
        onChange={handleInputChange('date')}
        horizontal
        wrapperClassName="mb-3 mt-3"
        min={getInputDate(hikingObstacle.date_in)}
        max={getInputDate(hikingObstacle.date_out)}
      />
      <PohInput
        type={InputTypes.textarea}
        disabled={isSaving}
        label="Комментарий"
        horizontal
        wrapperClassName="mb-3"
        value={data.comment}
        onChange={handleInputChange('comment')}
      />

      <footer className="border-top p-3 text-end">
        <PohButton type="submit" disabled={isSaving}>
          Сохранить
        </PohButton>
      </footer>
    </form>
  );
};

export default HikingObstaclePhotoEditForm;
